"a": "TEP: em que categorias da AHA/ACC 2026 a trombólise sistêmica é contraindicada e onde é razoável?",
"b": "AHA/ACC 2026: categorias A1 a C2, classe 3: Harm (mais sangramento maior e hemorragia intracraniana). Categoria E (choque), 2a; D (hipotensão transitória), 2b. Alteplase 100 mg em 2 horas; 25 a 50 mg pode ser considerada.",
