"a": "Profilaxia de endocardite antes de extração dentária no alto risco: qual esquema?",
"b": "ESC 2023 (classe I): amoxicilina 2 g VO 30 a 60 minutos antes; na alergia, cefalexina 2 g, azitromicina ou claritromicina 500 mg ou doxiciclina 100 mg. A clindamicina saiu pelo risco de C. difficile.",
