"a": "Mesalazina (5-ASA) na doença de Crohn: usar?",
"b": "Não. ECCO 2024 e AGA 2021 recomendam contra o 5-ASA no Crohn, para induzir e para manter. Crohn ileocecal leve induz com budesonida 9 mg/dia, que também não serve para manutenção.",
