"a": "Hepatite alcoólica grave em prednisolona: quando suspender?",
"b": "ACG 2024: Lille acima de 0,45 no 4º ou 7º dia é não resposta e o corticoide sai. Indicação é MELD acima de 20, prednisolona 40 mg/dia por 28 dias com N-acetilcisteína; pentoxifilina é contraindicada.",
