"a": "Esôfago de Barrett sem displasia: qual o intervalo de vigilância?",
"b": "ACG 2022: segmento menor que 3 cm, endoscopia a cada 5 anos; 3 cm ou mais, a cada 3 anos. Displasia de baixo grau confirmada: erradicação endoscópica preferida à vigilância.",
