"a": "Esofagite eosinofílica: qual o critério diagnóstico e como biopsiar?",
"b": "ACG 2025: sintoma de disfunção esofágica com 15 ou mais eosinófilos por campo de grande aumento, excluídas outras causas. Pelo menos 6 biópsias de 2 níveis, mesmo com mucosa normal. Teste alérgico não guia a dieta.",
