"a": "Hipoxemia e edema pulmonar bilateral horas após transfusão: como separar TRALI de TACO?",
"b": "TACO (ISBT 2018): hipertensão, jugular túrgida, BNP acima de 1,5 vez o basal; tratar com diurético. TRALI (consenso 2019): até 6 h, sem sobrecarga, pressão normal ou baixa; suporte ventilatório e sem diurético.",
