"a": "Prazos legais no SUS para o paciente com suspeita ou diagnóstico de câncer?",
"b": "Lei nº 13.896/2019: exames diagnósticos em até 30 dias diante de suspeita. Lei nº 12.732/2012: início do tratamento em até 60 dias após o diagnóstico de neoplasia maligna comprovada.",
